#include "camera_rigid_inverse_candidate.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");std::array<std::array<float,4>,3>world{{{0,-1,0,10},{1,0,0,20},{0,0,1,30}}};auto inverse=cameraRigidInverseCandidate(world);auto eye=inverse.clip({10,20,30});for(size_t n=0;n<3;++n)if(eye[n]!=0)throw std::runtime_error("eye origin");auto point=inverse.clip({8,21,33});if(point!=std::array<float,4>{1,2,3,1})throw std::runtime_error("rotated point");size_t rejected=0;world[0][1]=-2;try{cameraRigidInverseCandidate(world);}catch(const std::runtime_error&){++rejected;}world[0][1]=std::numeric_limits<float>::infinity();try{cameraRigidInverseCandidate(world);}catch(const std::runtime_error&){++rejected;}if(rejected!=2)throw std::runtime_error("basis rejection");std::cout<<"x64 camera rigid inverse candidate passed rejected="<<rejected<<" native_parity=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
